<script setup lang="ts">
import {chapters} from './profile-fields'
const props=defineProps<{step:number;ru:boolean;busy:boolean}>()
const emit=defineEmits<{step:[number];next:[];back:[];skip:[];exit:[];publish:[]}>()
</script>
<template><section class="profile-wizard" aria-labelledby="wizard-heading"><header class="profile-wizard-heading"><div><span class="profile-eyebrow">{{ru?'ПОШАГОВОЕ ЗАПОЛНЕНИЕ':'GUIDED PROFILE'}}</span><h2 id="wizard-heading" tabindex="-1">{{chapters[props.step-1]?.[ru?1:2]}}</h2><p class="muted">{{ru?'Можно заполнить сейчас или вернуться позже.':'Fill this in now or return later.'}}</p></div><button type="button" class="quiet-button" :disabled="busy" @click="emit('exit')">{{ru?'Сохранить и выйти':'Save & exit'}}</button></header><div class="profile-wizard-layout"><nav :aria-label="ru?'Шаги заполнения':'Profile steps'" class="profile-chapters"><button v-for="(chapter,index) in chapters" :key="chapter[0]" :aria-current="step===index+1?'step':undefined" :disabled="busy" @click="emit('step',index+1)"><span>{{index+1}}</span>{{chapter[ru?1:2]}}</button></nav><div class="profile-step-content"><p class="profile-step-counter">{{ru?'Шаг':'Step'}} {{step}} {{ru?'из':'of'}} 6</p><slot/><footer class="profile-wizard-actions"><button type="button" class="quiet-button" :disabled="busy||step===1" @click="emit('back')">← {{ru?'Назад':'Back'}}</button><button v-if="step<6" type="button" :disabled="busy" data-testid="profile-wizard-next" @click="emit('next')">{{busy?(ru?'Сохранение…':'Saving…'):(ru?'Сохранить и далее':'Save & continue')}} →</button><button v-else type="button" :disabled="busy" data-testid="profile-publish" @click="emit('publish')">{{busy?(ru?'Сохранение…':'Saving…'):(ru?'Сохранить профиль':'Publish profile')}}</button><button v-if="step<6" type="button" class="quiet-button" :disabled="busy" data-testid="profile-wizard-skip" @click="emit('skip')">{{ru?'Пропустить':'Skip'}}</button></footer></div></div></section></template>
